export interface AgentState {
  blocks: Block[]
  sessions: SessionMeta[]
  projects: ProjectMeta[]
  models: ModelOption[]
  snapshot: Snapshot
  streaming: boolean
  error?: string
}

const initial: AgentState = {
  blocks: [],
  sessions: [],
  projects: [],
  models: [],
  snapshot: { model: '加载中…', thinkingLevel: '高', cwd: '—', branch: '—', access: '变更前确认' },
  streaming: false
}

/** 引擎状态的唯一入口：发命令、收事件，view 只读它 */
export function useAgent(): AgentState & {
  prompt: (text: string) => void
  abort: () => void
  newSession: () => void
  openSession: (path: string) => void
  setModel: (id: string) => void
  setThinkingLevel: (level: string) => void
} {
  const [state, setState] = useState<AgentState>(initial)
  const ready = useRef(false)

  useEffect(() => {
    const api = window.pi?.agent
    // 浏览器里预览（无 preload）时降级为静态，不崩
    if (!api) {
      setState((s) => ({ ...s, error: '未连接到引擎（浏览器预览）' }))
      return
    }
    const off = api.onEvent((ev: AgentEvent) => {
      setState((s) => {
        switch (ev.type) {
          case 'sessions':
            return { ...s, sessions: ev.sessions, projects: ev.projects, models: ev.models }
          case 'reset':
            return { ...s, blocks: ev.blocks }
          case 'status':
            return { ...s, snapshot: ev.snapshot, streaming: ev.streaming }
          case 'error':
            return { ...s, error: ev.message }
          case 'settled':
            return { ...s, streaming: false }
          default:
            return s
        }
      })
    })
    if (!ready.current) {
      ready.current = true
      api.send({ type: 'init' })
    }
    return off
  }, [])

  const send = useCallback((fn: (a: Window['pi']['agent']) => void) => {
    if (window.pi?.agent) fn(window.pi.agent)
  }, [])

  return {
    ...state,
    prompt: (text) => send((a) => a.send({ type: 'prompt', text })),
    abort: () => send((a) => a.send({ type: 'abort' })),
    newSession: () => send((a) => a.send({ type: 'newSession' })),
    openSession: (path) => send((a) => a.send({ type: 'openSession', path })),
    setModel: (modelId) => send((a) => a.send({ type: 'setModel', modelId })),
    setThinkingLevel: (level) => send((a) => a.send({ type: 'setThinkingLevel', level }))
  }
}


